#!/usr/bin/env python3
"""Additive real loopback checks for text-only reports, corrections, photos and referral.
Private fixture is generated by technician_workbench.py --browser-fixture outside Git.
"""
import argparse,json,secrets
from pathlib import Path
from urllib.parse import urlsplit
from smoke import Client,Runner,expect,synthetic_imei
from case_tools import upload

def run(args):
 f=json.loads(Path(args.fixture).read_text());assert urlsplit(f['base']).hostname in ('127.0.0.1','localhost','::1');r=Runner(args.report);m=Client(f['base']);m.login(f['managerMobile'],f['password']);t=Client(f['base']);ta=t.login(f['tech']['phone'],f['password']);users=m.api('admin-users.php')['users'];other=next(u for u in users if u['role']=='technician' and u['id']!=ta['id']);o=Client(f['base']);o.login(other['phone'],f['password'])
 def create(wait_for_receipt=False):
  case_id= m.api('operations.php','POST',{'action':'create_case','receiptMode':'issue_only','customerName':'TEST minimal report','customerMobile':f['customerMobile'],'deviceModelId':f['model']['id'],'identifier':synthetic_imei(),'declaredIssue':'TEST روشن نمی‌شود','receptionNotes':'TEST ابتدا اتصال شارژ بررسی شود','customerConsent':{'dataHandling':'coordinate_first'},'assignedToUserId':ta['id'],'preapprovedAmount':7500000,'idempotencyKey':secrets.token_hex(14)})['repairCase']['id']
  if not wait_for_receipt: receive(case_id)
  return case_id
 def row(id,c=t):return c.api(f'workflow-v2.php?caseId={id}')['cases'][0]
 def proj(id,c=t):return c.api(f'workflow-v2.php?caseId={id}&technical=1')
 def receive(id):
  return t.api('workflow-v2.php','POST',{'action':'technical_receive','caseId':id,'lockVersion':row(id)['lockVersion'],'idempotencyKey':secrets.token_hex(12)})
 id=create(wait_for_receipt=True);before=row(id);p=proj(id)
 r.check('opening preserves status and version',lambda:expect(row(id)['status']==before['status'] and row(id)['lockVersion']==before['lockVersion'],'opening moved state'))
 r.check('necessary reception note is projected',lambda:expect(p['receptionNotes']=='TEST ابتدا اتصال شارژ بررسی شود','note absent'))
 payload={'action':'technical_activity','caseId':id,'description':'فقط نوشتن متن و ثبت گزارش','idempotencyKey':secrets.token_hex(12)}
 r.check('unchanged intake cannot create a technical note before physical receipt',lambda:t.api('workflow-v2.php','POST',payload,expected=409))
 r.check('receipt event carries real author and timestamp',lambda:expect(receive(id)['received'] and any(e['event_type']=='technical_receipt' and e['actorName']==ta['displayName'] and e['created_at'] for e in t.api(f'workflow-v2.php?caseId={id}&activity=1')['events']),'physical receipt audit missing'))
 first=r.check('text-only report needs no title or category',lambda:t.api('workflow-v2.php','POST',payload))
 r.check('text-only retry returns original event',lambda:expect(t.api('workflow-v2.php','POST',payload)['id']==first['id'],'duplicate report'))
 r.check('blank report rejected',lambda:t.api('workflow-v2.php','POST',{**payload,'description':'  ','idempotencyKey':secrets.token_hex(12)},expected=400))
 correction={**payload,'description':'اصلاح: اتصال باتری هم بررسی شد','correctsActivityId':first['id'],'idempotencyKey':secrets.token_hex(12)}
 second=r.check('correction appends independent immutable event',lambda:t.api('workflow-v2.php','POST',correction))
 r.check('original text survives correction',lambda:expect(len(proj(id)['activities']['activities'])==2 and next(a for a in proj(id)['activities']['activities'] if a['id']==first['id'])['description']==payload['description'],'original overwritten'))
 r.check('correction link retained',lambda:expect(proj(id)['activities']['activities'][0]['correctsActivityId']==first['id'],'link absent'))
 r.check('server author and time retained',lambda:expect(all(a['actorName']==ta['displayName'] and a['createdAt'] for a in proj(id)['activities']['activities']),'missing author/time'))
 foreign=create();fid=t.api('workflow-v2.php','POST',{**payload,'caseId':foreign,'idempotencyKey':secrets.token_hex(12)})['id']
 r.check('correction cannot link another case',lambda:t.api('workflow-v2.php','POST',{**correction,'correctsActivityId':fid,'idempotencyKey':secrets.token_hex(12)},expected=403))
 r.check('invalid correction ID rejected',lambda:t.api('workflow-v2.php','POST',{**correction,'correctsActivityId':1.5,'idempotencyKey':secrets.token_hex(12)},expected=400))
 r.check('unassigned technician cannot append correction',lambda:o.api('workflow-v2.php','POST',correction,expected=403))
 photo=r.check('optional photo uploads through existing private-file API',lambda:upload(t,id));files=t.api(f'files-v2.php?caseId={id}&technical=1')['files']
 r.check('photo list exposes server author and time',lambda:expect(any(x['publicId']==photo['publicId'] and x['uploadedBy']==ta['displayName'] and x['createdAt'] for x in files),'photo metadata absent'))
 private=upload(m,id,purpose='identity')
 r.check('technical gallery hides identity documents for manager too',lambda:expect(not any(x['publicId']==private['publicId'] for x in m.api(f'files-v2.php?caseId={id}&technical=1')['files']),'private evidence leaked into gallery'))
 r.check('general authorized file list remains backward compatible',lambda:expect(any(x['publicId']==private['publicId'] for x in m.api(f'files-v2.php?caseId={id}')['files']),'existing file list changed'))
 linked=t.api('workflow-v2.php','POST',{**payload,'description':'گزارش با پیوست اختیاری','attachments':[photo['publicId']],'idempotencyKey':secrets.token_hex(12)})
 r.check('photo links to a separate report',lambda:expect(proj(id)['activities']['activities'][0]['attachments']==[photo['publicId']],'attachment missing'))
 ref={'action':'handover_request','caseId':id,'toUserId':other['id'],'reason':'TEST ارجاع برای بررسی تخصصی','partsDisposition':'settle_before_handover','hotReturnsDisposition':'settle_before_handover','idempotencyKey':secrets.token_hex(12)}
 hand=r.check('explicit referral uses existing responsibility transfer',lambda:t.api('workflow-v2.php','POST',ref))
 r.check('referral request does not change owner or result',lambda:expect(row(id)['primaryTechnicianUserId']==ta['id'] and proj(id)['result'] is None,'referral faked a final outcome'))
 r.check('referral exact retry is idempotent',lambda:expect(t.api('workflow-v2.php','POST',ref)['publicId']==hand['publicId'],'duplicate referral'))
 r.check('referral retry cannot change destination reason',lambda:t.api('workflow-v2.php','POST',{**ref,'reason':'changed'},expected=409))
 r.check('other technician cannot replay referral',lambda:o.api('workflow-v2.php','POST',ref,expected=403))
 r.check('manager cannot bypass recipient confirmation',lambda:m.api('workflow-v2.php','POST',{'action':'handover_decide','publicId':hand['publicId'],'decision':'manager_force','reason':'TEST bypass removed'},expected=409))
 r.check('rejected manager force retains original responsibility',lambda:expect(row(id)['primaryTechnicianUserId']==ta['id'],'owner changed before confirmation'))
 receipt_endpoint=f"workflow-v2.php?handoverReceipt={hand['publicId']}"
 receipt=o.api(receipt_endpoint)
 decision={'action':'handover_decide','publicId':hand['publicId']}
 report={**decision,'decision':'report_discrepancy','reason':'TEST شارژر تحویل نشد'}
 resolve={**decision,'decision':'resolve_discrepancy','reason':'TEST مورد بررسی و رفع شد'}
 accept={**decision,'decision':'accept'}
 r.check('recipient receipt projects physical identifiers and no financial amounts',lambda:expect(receipt['receipt']['receiptNumber']==row(id)['receiptNumber'] and 'accessories' in receipt['receipt'] and all('price' not in k.lower() for k in receipt['receipt']),'incomplete or overexposed receipt'))
 r.check('receipt review is required for new referral',lambda:o.api('workflow-v2.php','POST',accept,expected=409))
 r.check('receipt checklist is required on server',lambda:o.api('workflow-v2.php','POST',{**accept,'receiptRevision':receipt['revision'],'checkedItems':[]},expected=409))
 r.check('only recipient can report a physical discrepancy',lambda:t.api('workflow-v2.php','POST',report,expected=403))
 r.check('recipient records a mismatch with no ownership change',lambda:expect(o.api('workflow-v2.php','POST',report)['status']=='requested' and row(id)['primaryTechnicianUserId']==ta['id'],'unexpected owner change'))
 r.check('duplicate report is idempotent',lambda:expect(o.api('workflow-v2.php','POST',report)['replayed'],'duplicate mismatch'))
 r.check('manager can read mismatch on receipt',lambda:expect(m.api(receipt_endpoint)['discrepancy']['reason']==report['reason'],'missing mismatch'))
 r.check('open discrepancy blocks recipient',lambda:o.api('workflow-v2.php','POST',{**accept,'receiptRevision':receipt['revision']},expected=409))
 r.check('technician cannot resolve discrepancy',lambda:o.api('workflow-v2.php','POST',resolve,expected=403))
 r.check('manager resolution keeps responsibility with sender',lambda:expect(m.api('workflow-v2.php','POST',resolve)['status']=='requested' and row(id)['primaryTechnicianUserId']==ta['id'],'manager changed owner'))
 r.check('receipt predating resolution is stale',lambda:o.api('workflow-v2.php','POST',{**accept,'receiptRevision':receipt['revision']},expected=409))
 fresh=o.api(receipt_endpoint)
 checklist=['device',*[part['publicId'] for group in ('partIssues','installedParts','hotReturns') for part in fresh['receipt'][group]]]
 accepted={**accept,'receiptRevision':fresh['revision'],'checkedItems':checklist}
 r.check('reviewed receipt can be accepted after resolution',lambda:expect(o.api('workflow-v2.php','POST',accepted)['status']=='accepted','handover did not complete'))
 r.check('accepted receipt persists and acceptance retry is idempotent',lambda:expect(o.api(receipt_endpoint)['receipt']==fresh['receipt'] and o.api('workflow-v2.php','POST',accepted)['replayed'],'accepted receipt was lost or transferred twice'))
 r.check('accepted referral preserves reports and original actor',lambda:expect(len(proj(id,o)['activities']['activities'])==3 and all(x['actorName']==ta['displayName'] for x in proj(id,o)['activities']['activities']),'transfer lost history'))
 r.check('former principal loses unauthorized edit access',lambda:t.api('workflow-v2.php','POST',{**payload,'idempotencyKey':secrets.token_hex(12)},expected=403))
 initial=create();state=row(initial)
 finish={'action':'technical_finish','caseId':initial,'result':'not_repaired','reason':'TEST برد قابل تعمیر نیست','report':'TEST برد قابل تعمیر نیست','lockVersion':state['lockVersion'],'idempotencyKey':secrets.token_hex(12)}
 r.check('no-repair decision follows physical receipt',lambda:t.api('workflow-v2.php','POST',finish))
 r.check('no-charge initial unrepaired case enters return without QC',lambda:expect(row(initial)['status']=='returned_unrepaired' and proj(initial)['result']=='not_repaired','wrong outcome'))
 r.check('closed case rejects text-only report',lambda:t.api('workflow-v2.php','POST',{**payload,'caseId':initial,'idempotencyKey':secrets.token_hex(12)},expected=409))
 r.check('closed case rejects photo',lambda:upload(t,initial,expected=409))
 r.check('closed case rejects referral',lambda:t.api('workflow-v2.php','POST',{**ref,'caseId':initial,'idempotencyKey':secrets.token_hex(12)},expected=409))
 blocked=create();inv=m.api('inventory-v2.php');item=inv['items'][0];t.api('inventory-v2.php','POST',{'action':'request','caseId':blocked,'itemId':item['id'],'quantity':1,'idempotencyKey':secrets.token_hex(12)})
 blocked_stage=row(blocked)['status']
 r.check('unsettled parts block initial no-repair completion',lambda:t.api('workflow-v2.php','POST',{**finish,'caseId':blocked,'lockVersion':row(blocked)['lockVersion'],'idempotencyKey':secrets.token_hex(12)},expected=409))
 r.check('failed initial finalization leaves result unset',lambda:expect(proj(blocked)['result'] is None and row(blocked)['status']==blocked_stage,'partial result committed'))
 closed_ref=create();ch=t.api('workflow-v2.php','POST',{**ref,'caseId':closed_ref,'idempotencyKey':secrets.token_hex(12)});t.api('workflow-v2.php','POST',{**finish,'caseId':closed_ref,'lockVersion':row(closed_ref)['lockVersion'],'idempotencyKey':secrets.token_hex(12)})
 r.check('closed case cannot accept an earlier pending handover',lambda:o.api('workflow-v2.php','POST',{'action':'handover_decide','publicId':ch['publicId'],'decision':'accept'},expected=409))
 r.check('failed closed-case handover retains owner and lock',lambda:expect(row(closed_ref)['primaryTechnicianUserId']==ta['id'] and row(closed_ref)['isLocked'],'closed ownership mutated'))
 r.check('closed-case pending handover may still be cancelled by manager',lambda:m.api('workflow-v2.php','POST',{'action':'handover_decide','publicId':ch['publicId'],'decision':'cancel','reason':'TEST لغو ارجاع پرونده بسته'}))
 r.metadata={'scope':'New minimal workspace API additions only; existing workflow matrix is a separate regression','no_sms_or_customer_approval':True};r.save();print('PASS',len(r.results),'minimal API checks')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--fixture',required=True);p.add_argument('--report',required=True);run(p.parse_args())
